args.command:
node --input-type=module <<'EOF'
import { permit } from './limit.mjs';
const cases = [[-1,false],[0,true],[1,true],[2,true],[3,true],[4,false],[1.5,false]];
for (const [v, exp] of cases) {
  const got = permit(v);
  console.log(`${v}: ${got} expected ${exp}`);
  if (got !== exp) process.exitCode = 1;
}
EOF
